    return returncode if returncode >= 0 else 1


def deno_missing(kind):
    action = 'start' if kind == 'stdin' else 'run'
    mode = 'inline' if kind == 'code' else kind
    return ("failed to {} Deno for {} execution because 'deno' was not found in PATH. "
            'Install Deno from https://deno.land/manual/getting_started/installation '
            'or ensure the binary is available on your PATH.').format(action, mode)


