    for name in COMMANDS[lang]:
        path = shutil.which(name)
        if path:
            return path
    if lang == 'bash':
        return '/bin/bash'
    if lang in MISSING:
        raise RunError(MISSING[lang])
    if lang == 'typescript':
        raise RunError(deno_missing(kind))
    if kind == 'stdin':
        name = COMMANDS[lang][0]
        raise RunError('failed to start {} for stdin execution'.format(name), 'No such file or directory (os error 2)')
    raise RunError('No such file or directory (os error 2)')


