    root = os.environ.get('TMPDIR') or '/tmp'
    alphabet = string.ascii_letters + string.digits
    path = None
    try:
        for _ in range(100):
            candidate = os.path.join(root, prefix + ''.join(secrets.choice(alphabet) for _ in range(6)))
            try:
                os.mkdir(candidate, 0o700)
                path = candidate
                break
            except FileExistsError:
                pass
