import os
import sys
from .cli import parse, select, CliExit, VERSION
from .detection import detect
from .errors import RunError, print_error, os_message
from .backends import execute


def main():
    name = os.path.basename(sys.argv[0]) or 'executable'
    try:
        options = parse(sys.argv[1:], name)
        if options.version:
            sys.stdout.write(VERSION)
            return 0
        request = select(options)
        if request.kind == 'stdin' and sys.stdin.isatty():
            from .repl import repl
            return repl(request.lang or 'python', request.detect)
        if request.kind == 'stdin':
            try:
                request.data = sys.stdin.buffer.read().decode('utf-8')
            except (OSError, UnicodeError) as e:
                raise RunError('failed to materialize execution payload', os_message(e))
        lang = request.lang
        if lang is None and request.detect and request.kind in ('code', 'stdin'):
            lang = detect(request.data)
        return execute(lang or 'python', request.kind, request.data)
    except CliExit as e:
        stream = sys.stdout if e.code == 0 else sys.stderr
        stream.write(e.text)
        return e.code
    except RunError as e:
        print_error(e)
        return 1
    except KeyboardInterrupt:
        return 1
    except BrokenPipeError:
        return 1


if __name__ == '__main__':
    sys.exit(main())
