"""Terminal sessions with replayable state and incremental output."""
import ast
import io
import json
import os
import re
import subprocess
import sys
import time
import tokenize
from contextlib import ExitStack
from .catalog import canonical, NAMES, MISSING
from .detection import detect as detect_language
from .errors import RunError, os_message
from .backends import runtime, temp_directory, save, call, status, execute, write_out

HELP = '''Commands:
  :help                 Show this help message
  :languages            List available languages
  :lang <id>            Switch to language <id>
  :detect on|off        Enable or disable auto language detection
  :reset                Reset the current language session
  :load <path>          Execute a file in the current language
  :exit, :quit          Leave the REPL
Any language id or alias works as a shortcut, e.g. :py, :cpp, :csharp, :php.
'''

# Parsing and compiling the user's syntax tree preserves its source coordinates,
# while allowing a single expression to use the REPL's display convention.
PYTHON_DRIVER = r'''
import ast, sys, traceback, os, json
path = sys.argv[1]
lines = set(json.loads(sys.argv[2]))
sys.argv = [path]
sys.path[0] = os.path.dirname(path)
try:
    with open(path, encoding='utf-8') as f:
        text = f.read()
    tree = ast.parse(text, path)
    for n in tree.body:
        if isinstance(n, ast.Expr) and n.lineno in lines:
            n.value = ast.copy_location(ast.Call(func=ast.Name(id='print', ctx=ast.Load()), args=[ast.Call(func=ast.Name(id='repr', ctx=ast.Load()), args=[n.value], keywords=[])], keywords=[]), n.value)
    ast.fix_missing_locations(tree)
    environment = {'__name__': '__main__', '__file__': path, '__package__': None, '__cached__': None}
    exec(compile(tree, path, 'exec'), environment)
except SystemExit as error:
    raise SystemExit(error.code)
except BaseException as error:
    tb = error.__traceback__
    while tb is not None and tb.tb_frame.f_code.co_filename != path:
        tb = tb.tb_next
    traceback.print_exception(type(error), error, tb)
    raise SystemExit(1)
'''

C_PRINTING = '''
#include <stdio.h>
static void run_print_s(const char *v) { printf("%s\\n", v ? v : "(null)"); }
static void run_print_i(long long v) { printf("%lld\\n", v); }
static void run_print_u(unsigned long long v) { printf("%llu\\n", v); }
static void run_print_f(double v) { printf("%.17g\\n", v); }
static void run_print_ld(long double v) { printf("%.21Lg\\n", v); }
static void run_print_p(const void *v) { printf("%p\\n", v); }
#define RUN_PRINT(v) _Generic((v), char*:run_print_s, const char*:run_print_s, float:run_print_f, double:run_print_f, long double:run_print_ld, char:run_print_i, signed char:run_print_i, short:run_print_i, int:run_print_i, long:run_print_i, long long:run_print_i, unsigned char:run_print_u, unsigned short:run_print_u, unsigned int:run_print_u, unsigned long:run_print_u, unsigned long long:run_print_u, default:run_print_p)(v)
'''


def python_expression(source):
    if re.match(r'^print\s*\(', source.lstrip()):
        return False
    try:
        ast.parse(source, mode='eval')
        return True
    except (SyntaxError, ValueError):
        return False


def expression_like(source, lang):
    text = source.strip()
    if not text or '\n' in text or text.endswith((';','}')):
        return False
    starters = r'^(?:let|use|fn|import|var|const|type|int|float|double|long|char|unsigned|short|struct|enum|typedef|return|if|for|while|switch|class|namespace|my|our|sub|print|say)\b'
    if re.search(starters, text):
        return False
    if re.search(r'(?<![=<>!:])=(?!=)', text) or ':=' in text:
        return False
    return True


class Session:
    def __init__(self, language, stack):
        self.language = language
        if language == 'javascript':
            try:
                runtime(language)
            except RunError:
                raise RunError('failed to start javascript session', '0: failed to start node REPL\n1: No such file or directory (os error 2)')
        elif language == 'typescript':
            try:
                runtime(language)
            except RunError:
                raise RunError('failed to start typescript session', "failed to invoke Deno to check its version because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH.")
        self.program = runtime(language)
        prefix = '.tmp' if language in ('c', 'cpp') else 'run-' + language + '-repl'
        self.folder = stack.enter_context(temp_directory(prefix))
        self.history = []
        self.stdout = b''
        self.stderr = b''

    def capture(self, argv):
        try:
            return subprocess.run(argv, cwd=self.folder, stdin=subprocess.DEVNULL,
                                  stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except OSError as e:
            raise RunError(os_message(e))

    def python(self, history):
        text = '\n\n\n'
        expression_lines = []
        for code in history:
            first_line = text.count('\n') + 1
            expr = python_expression(code)
            if expr:
                expression_lines.append(first_line)
            text += code + ('\n\n' if expr else '\n')
        path = os.path.join(self.folder, 'session.py')
        save(path, text)
        return self.capture([self.program, '-c', PYTHON_DRIVER, path, json.dumps(expression_lines)])

    def shell(self, history):
        path = os.path.join(self.folder, 'session.sh')
        save(path, '\n'.join(history) + '\n')
        return self.capture([self.program, path])

    def perl(self, history):
        text = 'use strict;\nuse warnings;\n\n\n'
        for code in history:
            if expression_like(code, 'perl'):
                text += 'print((' + code + '), "\\n");\n'
            else:
                text += code + '\n'
        save(os.path.join(self.folder, 'session.pl'), text)
        return self.capture([self.program, 'session.pl'])

    def compiled(self, history, transform=True):
        lang = self.language
        body, top = [], []
        for code in history:
            item = code
            if lang == 'go' and code.strip().startswith('import '):
                top.append(code.strip())
                continue
            if transform and expression_like(code, lang):
                if lang == 'c':
                    item = 'RUN_PRINT((' + code.strip() + '));'
                elif lang == 'cpp':
                    item = 'std::cout << (' + code.strip() + ') << std::endl;'
                elif lang == 'rust':
                    item = 'println!("{:?}", (' + code.strip() + '));'
                elif lang == 'go':
                    item = 'fmt.Println(' + code.strip() + ')'
            if lang in ('c', 'cpp') and item.lstrip().startswith('#'):
                top.append(item)
            else:
                body.extend('    ' + line for line in item.splitlines())
        body_text = '\n'.join(body)
        if lang == 'c':
            header = C_PRINTING + '\n'.join(top) + '\n'
            header += '\n' * max(0, 28 - header.count('\n'))
            text = header + 'int main(void)\n{\n' + body_text + '\n    return 0;\n}\n'
            file = 'main.c'
            flags = ['-std=c11', '-Wall', '-Wextra']
        elif lang == 'cpp':
            text = '#include <iostream>\n#include <string>\n#include <vector>\n#include <map>\n#include <cmath>\n#include <algorithm>\n' + '\n'.join(top) + '\nint main() {\n' + body_text + '\n}\n'
            file = 'main.cpp'
            flags = ['-std=c++17', '-Wall', '-Wextra']
        elif lang == 'rust':
            text = 'fn main() {\n' + body_text + '\n}\n'
            file = 'main.rs'
            flags = ['--edition=2021', '--crate-name', 'run_repl']
        else:
            imports = '\n'.join(top)
            if 'fmt.' in body_text and not re.search(r'["\']fmt["\']', imports):
                imports += '\nimport "fmt"'
            text = 'package main\n' + imports + '\nfunc main() {\n' + body_text + '\n}\n'
            file = 'main.go'
            save(os.path.join(self.folder, file), text)
            return self.capture([self.program, 'run', file])
        path = os.path.join(self.folder, file)
        save(path, text)
        binary = os.path.join(self.folder, 'run_repl_binary')
        p = self.capture([self.program] + flags + [path, '-o', binary])
        if p.returncode:
            return p
        return self.capture([binary])

    def evaluate(self, source):
        history = self.history + [source]
        start = time.monotonic()
        if self.language == 'python':
            result = self.python(history)
        elif self.language == 'bash':
            result = self.shell(history)
        elif self.language == 'perl':
            result = self.perl(history)
        elif self.language in ('c','cpp','rust','go'):
            result = self.compiled(history)
            if result.returncode and self.language == 'c' and expression_like(source, 'c'):
                result = self.compiled(history, transform=False)
        else:
            # The remaining adapters use their normal inline forms when installed.
            from .catalog import EXTENSIONS
            extension = next((k for k, v in EXTENSIONS.items() if v == self.language), 'txt')
            file = os.path.join(self.folder, 'session.' + extension)
            save(file, '\n'.join(history))
            result = self.capture([self.program, file])
        elapsed = int((time.monotonic() - start)*1000)
        out, err = result.stdout, result.stderr
        if self.stdout and out.startswith(self.stdout):
            out = out[len(self.stdout):]
        if self.stderr and err.startswith(self.stderr):
            err = err[len(self.stderr):]
        # A REPL response always ends on its own terminal line.
        if out and not out.endswith(b'\n'):
            out += b'\n'
        if err and not err.endswith(b'\n'):
            err += b'\n'
        write_out(out, sys.stdout)
        write_out(err, sys.stderr)
        code = status(result.returncode)
        if code:
            print('[exit code {}] ({}ms)'.format(code, elapsed))
        else:
            self.history = history
            self.stdout, self.stderr = result.stdout, result.stderr


def incomplete(source, language, suite=False):
    if language == 'python':
        if suite:
            return not source.endswith('\n\n')
        if source.rstrip().endswith(':'):
            return True
        try:
            list(tokenize.generate_tokens(io.StringIO(source).readline))
        except tokenize.TokenError as e:
            return 'multi-line' in str(e)
        except (IndentationError, SyntaxError):
            return False
        return source.rstrip().endswith('\\')
    # Account for delimiters, excluding quoted text and line comments.
    clean = re.sub(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|//[^\n]*', '', source)
    return any(clean.count(a) > clean.count(b) for a,b in [('(',')'),('[',']'),('{','}')]) or source.rstrip().endswith('\\')


def repl(language='python', autodetect=True):
